INSERT INTO visits (id, animal_id, visit_date, presenting_complaint, observations, severity, temperature_celsius, treatment_notes, follow_up_notes) VALUES (1, 1, '2026-10-11', 'High fever, persistent nasal discharge, severe appetite loss', 'Rectal temperature elevated. Bilateral seromucous nasal discharge. Dull demeanor, ruminal stasis detected. Lung auscultation indicates bronchial rales.', 'SEVERE', 40.1, 'Administered antipyretic (Meloxicam 0.5mg/kg), broad-spectrum antibiotic supportive cover (Oxytetracycline LA), and oral electrolyte drench.', 'Isolate affected animal in separate pen. Monitor rectal temperature twice daily. Review herd biosecurity.') ON CONFLICT (id) DO NOTHING;
